def continuousMapHalfBoundInverse (a : C(K, 𝕜)) (ha : ∀ x, 1 / 2 ≤ ‖a x‖) : C(K, 𝕜) :=
  ⟨fun x => (a x)⁻¹, a.continuous.inv₀ (fun x => norm_pos_iff.mp
    ((by norm_num : (0 : ℝ) < 1 / 2).trans_le (ha x)))⟩

